#include <iostream>
#include <iomanip>
#include <cstddef>

int main() {
    // C-style array as presented in Section 6.2 / Fig. 6.1
    int c[12] = {-45, 6, 0, 72, 1543, -89, 0, 62, -3, 1, 6453, 78};

    int a = 5;
    int b = 6;

    // Using an integer expression as subscript and modifying as lvalue
    c[a + b] += 2; // c[11] was 78, now becomes 80
    c[2] = 1000;   // Assigning directly via lvalue

    // Division of array element
    int x = c[6] / 2;

    std::cout << "c[0] + c[1] + c[2] = " << (c[0] + c[1] + c[2]) << "\n";
    std::cout << "x = " << x << "\n";
    std::cout << "Updated c[11] = " << c[11] << "\n";

    // Demonstrating contiguous memory addresses
    bool is_contiguous = true;
    for (size_t i = 1; i < 12; ++i) {
        std::ptrdiff_t diff = reinterpret_cast<char*>(&c[i]) - reinterpret_cast<char*>(&c[i - 1]);
        if (diff != sizeof(int)) {
            is_contiguous = false;
        }
    }
    std::cout << "Contiguous layout: " << (is_contiguous ? "true" : "false") << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>
#include <array>

int main() {
    // C-style array demonstrated in Section 6.4.1
    constexpr std::size_t array_size = 5;
    int n[array_size]; // Contains garbage until initialized

    // Set elements of array n to 0 using a for loop
    for (std::size_t i = 0; i < array_size; ++i) {
        n[i] = 0;
    }

    // Output tabular format
    std::cout << std::setw(7) << "Element" << std::setw(13) << "Value" << "\n";
    for (std::size_t i = 0; i < array_size; ++i) {
        std::cout << std::setw(7) << i << std::setw(13) << n[i] << "\n";
    }

    // Modern C++17 equivalent using std::array
    std::array<int, array_size> modern_arr{}; // Value-initialized to all zeros
    int sum = 0;
    for (int val : modern_arr) {
        sum += val;
    }
    std::cout << "Modern std::array sum: " << sum << "\n";

    return 0;
}
